@implementation Main

- (void)solve:(NSScanner *)in out:(NSFileHandle *)out {
    int N;
    [in scanInt:&N];
    NSMutableDictionary *hash = [NSMutableDictionary dictionary];
    for (int i = 1; i <= N; i++) {
        [hash setObject:@([self dividedCount:i]) forKey:@(i)];
    }

    NSArray *sortedKeys = [[hash allKeys] sortedArrayUsingComparator:^NSComparisonResult(id obj1, id obj2) {
        return [[hash objectForKey:obj2] compare:[hash objectForKey:obj1]];
    }];

    NSData *data = [[NSString stringWithFormat:@"%d\n", [sortedKeys[0] intValue]] dataUsingEncoding:NSUTF8StringEncoding];
    [out writeData:data];
}

- (int)dividedCount:(int)n {
    if (n % 2 != 0 || n <= 1) {
        return 0;
    }
    return 1 + [self dividedCount:n/2];
