#import <Foundation/Foundation.h>

int R;
int G;
int B;
int N;

void input() {
    NSFileHandle *input = [NSFileHandle fileHandleWithStandardInput];
    NSData *data = [input availableData];
    NSString *inputString = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
    NSArray *inputArray = [inputString componentsSeparatedByString:@" "];
    R = [[inputArray objectAtIndex:0] intValue];
    G = [[inputArray objectAtIndex:1] intValue];
    B = [[inputArray objectAtIndex:2] intValue];
    N = [[inputArray objectAtIndex:3] intValue];
}

void solve() {
    int ans = 0;
    int r = 0;
    int g = 0;
    int b = 0;
    while (r * R <= N) {
        int k = N - r * R;
        g = 0;
        while (g * G <= k) {
            int l = k - g * G;
            if (l % B == 0) {
                ans++;
            }
            g++;
        }
        r++;
    }
    NSLog(@"%d", ans);
}

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        input();
        solve();
    }
    return 0;
}

