                for (int j = 0; j <= 3000; j++) {
                    int g = numList.get(1) * j;
                    if (r + g > target) {
                        break;
                    }
                    for (int k = 0; k <= 3000; k++) {
                        int b = numList.get(2) * k;
                        if (r + g + b == target) {
                            ans++;
                        }
                    }
                }
            }
            System.out.println(ans);
        };
    }
